item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic c,
    input  logic d,
    output logic q
);
    assign q = b | c;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic a, b, c, d;
    wire q;
    // Bit index is the binary value of {a,b,c,d}, from original waveform.
    localparam logic [15:0] EXPECTED = 16'"'b1111110011111100;
    integer i;
    integer checks = 0;
    TopModule dut (.a(a), .b(b), .c(c), .d(d), .q(q));
    task automatic check(input integer index);
        begin
            {a,b,c,d} = index[3:0];
            #1;
            if (q "'!== EXPECTED[index])
                $fatal(1, "FAIL input=%04b expected=%b actual=%b", {a,b,c,d}, EXPECTED[index], q);
            checks = checks + 1;
        end
    endtask
    initial begin
        for (i = 0; i < 16; i = i + 1) check(i);
        for (i = 15; i >= 0; i = i - 1) check(i);
        $display("PASS: %0d truth-table checks, all 16 combinations in both orders", checks);
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > development_compile.log 2>&1
compile_status=$?
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > development_simulation.log 2>&1
    sim_status=$?
else
    sim_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$sim_status" > development_status.log
cat development_status.log development_compile.log development_simulation.log'

